<script>
(()=>{const el=document.getElementById('featured-data');if(!el)return;const data=JSON.parse(el.textContent),grid=document.getElementById('featured-grid'),tabs=[...document.querySelectorAll('.featured-tabs button')];let active='Venta';function shuffle(a){return [...a].sort(()=>Math.random()-.5).slice(0,4)}function render(){const items=shuffle(data[active]||[]);grid.innerHTML='';if(!items.length){grid.innerHTML='<p class="empty">Próximamente agregaremos propiedades de '+active.toLowerCase()+'.</p>';return;}items.forEach(p=>{const card=document.createElement('article');card.className='property';const img=document.createElement('img');img.src=p.image||'assets/logo-alianza.png';img.alt=p.title;const pad=document.createElement('div');pad.className='pad';const tag=document.createElement('span');tag.className='tag';tag.textContent=p.operation+' · '+p.type;const h=document.createElement('h3');h.textContent=p.title;const loc=document.createElement('p');loc.className='muted';loc.textContent=p.location;const price=document.createElement('b');price.className='price';price.textContent='$'+Number(p.price).toLocaleString('es-MX')+' MXN'+(p.operation==='Renta'?' / mes':'');const detail=document.createElement('a');detail.className='featured-link';detail.href='property.php?id='+p.id;detail.textContent='Ver información completa →';const link=document.createElement('a');link.className='featured-link';link.href='https://wa.me/523324248110?text='+encodeURIComponent('Hola, me interesa esta propiedad:\n'+p.title+'\nUbicación: '+p.location+'\nPrecio: $'+Number(p.price).toLocaleString('es-MX')+' MXN\nVer propiedad: https://www.alianzainmob.com/property.php?id='+p.id);link.target='_blank';link.rel='noopener';link.textContent='Solicitar información por WhatsApp ↗';pad.append(tag,h,loc,price,detail,link);card.append(img,pad);grid.append(card);});}tabs.forEach(b=>b.addEventListener('click',()=>{active=b.dataset.tab;tabs.forEach(x=>x.classList.toggle('active',x===b));render();}));render();setInterval(render,5000);})();
</script><script>document.addEventListener("DOMContentLoaded",()=>{const viewport=document.getElementById("home-youtube-viewport");if(!viewport)return;const buttons=[...document.querySelectorAll(".home-youtube-arrow")];const step=()=>{const card=viewport.querySelector(".home-youtube-item");if(!card)return viewport.clientWidth;const gap=parseFloat(getComputedStyle(viewport.querySelector(".home-youtube-grid")).gap)||0;return card.getBoundingClientRect().width+gap;};buttons.forEach(button=>button.addEventListener("click",()=>viewport.scrollBy({left:Number(button.dataset.videoDirection)*step(),behavior:"smooth"})));const update=()=>{const max=viewport.scrollWidth-viewport.clientWidth;buttons.forEach(b=>{const dir=Number(b.dataset.videoDirection);b.disabled=dir<0?viewport.scrollLeft<4:viewport.scrollLeft>=max-4;b.style.opacity=b.disabled?".35":"1";});};viewport.addEventListener("scroll",update,{passive:true});window.addEventListener("resize",update);update();});</script></body></html>